const readline = require('readline');

function checkUser(t) {
    let c = 0;
    let Next = false;
    let sc = 0;

    for (let i = 0; i < t.length; i++) {
        if (t[i] === '@') {
            if (i + 1 === t.length) return false;
            Next = (c > 0 && c < 17);
            sc = i + 1;
            break;
        }
        if (!((t[i] >= 'a' && t[i] <= 'z') || (t[i] >= 'A' && t[i] <= 'Z') || (t[i] >= '0' && t[i] <= '9') || t[i] === '_')) {
            return false;
        }
        c++;
    }

    if (Next) {
        Next = false;
        let SNext = false;
        c = 0;
        let Turn = false;
        let Slash = false;

        for (let i = sc; i < t.length; i++) {
            if (i + 1 === t.length && t[i] === '.') return false;
            if (t[i] === '/') {
                if (i - 1 > 0 && t[i - 1] === '.') return false;
                Slash = true;
                if (Turn === false) {
                    SNext = true;
                }
                sc = i + 1;
                break;
            }

            if (t[i] === '.') {
                Turn = true;
                if (c > 0 && c < 17) {
                    c = 0;
                    continue;
                } else {
                    return false;
                }
            }

            if (!((t[i] >= 'a' && t[i] <= 'z') || (t[i] >= 'A' && t[i] <= 'Z') || (t[i] >= '0' && t[i] <= '9') || (t[i] === '_'))) {
                return false;
            }
            c++;
        }

        if (!SNext && Slash) {
            c = 0;
            for (let i = sc; i < t.length; i++) {
                if (!((t[i] >= 'a' && t[i] <= 'z') || (t[i] >= 'A' && t[i] <= 'Z') || (t[i] >= '0' && t[i] <= '9') || (t[i] === '_'))) {
                    return false;
                }
                c++;
            }
            if (c > 0 && c < 17) return true;
            return false;
        } else {
            if (Slash) {
                c = 0;
                for (let i = sc; i < t.length; i++) {
                    if (!((t[i] >= 'a' && t[i] <= 'z') || (t[i] >= 'A' && t[i] <= 'Z') || (t[i] >= '0' && t[i] <= '9') || (t[i] === '_'))) {
                        return false;
                    }
                    c++;
                }
                if (c > 0 && c < 17) return true;
                return false;
            }
            return true;
        }
    } else {
        return false;
    }
}

const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});

rl.on('line', (line) => {
    const Id = line.trim();
    if (checkUser(Id)) {
        console.log("YES");
    } else {
        console.log("NO");
    }
    rl.close();
});

const fs = require('fs');

function checkUser(t) {
    let c = 0;
    let Next = false;
    let sc = 0;

    for (let i = 0; i < t.length; i++) {
        if (t[i] === '@') {
            if (i + 1 === t.length) return false;
            Next = (c > 0 && c < 17);
            sc = i + 1;
            break;
        }
        const ch = t[i];
        if (!((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || (ch >= '0' && ch <= '9') || ch === '_')) {
            return false;
        }
        c++;
    }

    if (Next) {
        let SNext = false;
        c = 0;
        let Turn = false;
        let Slash = false;

        for (let i = sc; i < t.length; i++) {
            if (i + 1 === t.length && t[i] === '.') return false;

            if (t[i] === '/') {
                if (i - 1 > 0 && t[i - 1] === '.') return false;
                Slash = true;
                if (Turn === false) SNext = true;
                sc = i + 1;
                break;
            }

            if (t[i] === '.') {
                Turn = true;
                if (c > 0 && c < 17) {
                    c = 0;
                    continue;
                } else {
                    return false;
                }
            }

            const ch = t[i];
            if (!((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || (ch >= '0' && ch <= '9') || ch === '_')) {
                return false;
            }
            c++;
        }

        if (!SNext && Slash) {
            c = 0;
            for (let i = sc; i < t.length; i++) {
                const ch = t[i];
                if (!((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || (ch >= '0' && ch <= '9') || ch === '_')) {
                    return false;
                }
                c++;
            }
            if (c > 0 && c < 17) return true;
            return false;
        } else {
            if (Slash) {
                c = 0;
                for (let i = sc; i < t.length; i++) {
                    const ch = t[i];
                    if (!((ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || (ch >= '0' && ch <= '9') || ch === '_')) {
                        return false;
                    }
                    c++;
                }
                if (c > 0 && c < 17) return true;
                return false;
            }
            return true;
        }
    } else {
        return false;
    }
}

const input = fs.readFileSync(0, 'utf8').trim();
const Id = input.split(/\s+/)[0];

if (checkUser(Id)) {
    console.log("YES");
} else {
    console.log("NO");
}

